_BUNDLE_SOURCES = _bundle_json.loads(r"""{"pcve_project_paths": "\"\"\"Path helpers shared by standalone rigid-scene folders.\"\"\"\nfrom pathlib import Path\nimport sys\n\n\ndef project_root(anchor):\n    anchor = Path(anchor).resolve()\n    candidates = (anchor, *anchor.parents)\n    for candidate in candidates:\n        if (candidate / \"assets\").is_dir() and (candidate / \"clean_scripts\").is_dir():\n            return candidate\n    raise FileNotFoundError(f\"Cannot locate project root above {anchor}; expected assets/ and clean_scripts/\")\n\n\ndef scene_root(anchor):\n    \"\"\"Find the scene folder from argv first, then from the helper's parents.\"\"\"\n    candidates = []\n    if sys.argv and sys.argv[0] not in {\"-\", \"\"}:\n        argv_path = Path(sys.argv[0]).expanduser()\n        if not argv_path.is_absolute():\n            argv_path = Path.cwd() / argv_path\n        candidates.append(argv_path.resolve().parent)\n    anchor = Path(anchor).resolve()\n    candidates.extend(anchor.parents)\n    seen = set()\n    for candidate in candidates:\n        if candidate in seen:\n            continue\n        seen.add(candidate)\n        if any(candidate.glob(\"simulate_*.py\")) and any(candidate.glob(\"render_*.py\")):\n            return candidate\n    raise FileNotFoundError(f\"Cannot locate scene entrypoints above {anchor}\")\n", "pcve_scene_runtime": "\"\"\"Shared command-line and output contracts for PCVE scene entry points.\n\nBoth ``blender -b --python render.py -- ...`` and Python with bpy are supported.\nThis module has no Blender dependency until a renderer finishes.\n\"\"\"\n\nimport argparse\nimport hashlib\nimport json\nimport math\nimport os\nimport random\nimport shutil\nimport sys\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\n_render_args = None\n\n\ndef python_for(role: str) -> Path:\n    override = os.environ.get(\"PCVE_PHYSICS_PYTHON\" if role == \"physics\" else \"PCVE_RENDER_PYTHON\")\n    if override:\n        return Path(override).expanduser()\n    names = (\"sim/python.exe\", \"sim/bin/python\") if role == \"physics\" else (\n        \"render/Scripts/python.exe\", \"render/bin/python\")\n    for base in (ROOT / \".runtime\", ROOT.parent / \"PCVE-ElasticBench/.runtime\"):\n        for name in names:\n            if (base / name).is_file():\n                return base / name\n    if role == \"physics\":\n        # The original Linux setup activates a PyBullet conda environment and\n        # invokes Blender separately. Blender's sys.executable is not Python.\n        candidates = [ROOT.parent / \"miniconda/envs/physics/bin/python\"]\n        if os.environ.get(\"CONDA_PREFIX\"):\n            prefix = Path(os.environ[\"CONDA_PREFIX\"])\n            candidates += [prefix / \"python.exe\", prefix / \"bin/python\"]\n        for name in (\"python3\", \"python\"):\n            if shutil.which(name):\n                candidates.append(Path(shutil.which(name)))\n        for candidate in candidates:\n            if candidate.is_file() and \"blender\" not in candidate.name.lower():\n                return candidate\n    return Path(sys.executable)\n\n\ndef _add(parser, flag, **kwargs):\n    if flag not in parser._option_string_actions:\n        parser.add_argument(flag, **kwargs)\n\n\ndef implementation_hashes(directory):\n    files = list(Path(directory).glob(\"*.py\"))\n    files += [ROOT / \"clean_scripts\" / name for name in (\"pcve_scene_pipeline.py\", \"pcve_edit_dsl.py\")]\n    return {str(path.relative_to(ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n            for path in files if path.is_file()}\n\n\ndef case_outputs(folder):\n    \"\"\"Semantic output keys used by the original suite manifests.\"\"\"\n    names = dict(video=\"video.mp4\", ground_truth=\"ground_truth_transforms.json\",\n                 scenario_metadata=\"scenario_metadata.json\", scenario_overrides=\"scenario_overrides.json\",\n                 physics=\"physics_transforms.json\", scenario_input=\"scenario_input.json\", preview=\"preview.png\")\n    return {key: str((Path(folder) / name).resolve()) for key, name in names.items()\n            if (Path(folder) / name).is_file()}\n\n\ndef add_build_arguments(parser):\n    _add(parser, \"--blender\", type=Path, help=\"Blender executable; otherwise use render Python with bpy.\")\n    _add(parser, \"--physics-python\", type=Path, default=python_for(\"physics\"))\n    _add(parser, \"--render-python\", type=Path, default=python_for(\"render\"))\n    _add(parser, \"--engine\", choices=(\"cycles\", \"eevee\"), default=\"cycles\")\n    _add(parser, \"--device\", choices=(\"auto\", \"cpu\"), default=\"auto\")\n    _add(parser, \"--preview-frame\", type=int)\n    _add(parser, \"--fps\", type=int)\n    _add(parser, \"--duration-sec\", type=float)\n    return parser\n\n\ndef render_prefix(args, script: Path) -> list[str]:\n    blender = getattr(args, \"blender\", None) or os.environ.get(\"BLENDER_BIN\")\n    render_python = Path(getattr(args, \"render_python\", python_for(\"render\")))\n    if not blender and render_python == Path(sys.executable):\n        candidates = [ROOT / \"tools/blender-3.6.23-linux-x64/blender\"]\n        if shutil.which(\"blender\"):\n            candidates.append(Path(shutil.which(\"blender\")))\n        blender = next((path for path in candidates if path.is_file()), None)\n    if blender:\n        # Blender otherwise returns success even when the Python script raises.\n        return [str(Path(blender).expanduser()), \"-b\", \"--python-exit-code\", \"1\",\n                \"--python\", str(script), \"--\"]\n    return [str(render_python), str(script)]\n\n\ndef append_render_options(command, args):\n    for name in (\"engine\", \"device\", \"preview_frame\"):\n        flag = \"--\" + name.replace(\"_\", \"-\")\n        value = getattr(args, name, None)\n        if value is not None and flag not in command:\n            command += [flag, str(value)]\n    return command\n\n\ndef parse_render_args(parser, argv=None):\n    global _render_args\n    _add(parser, \"--seed\", type=int, default=0)\n    _add(parser, \"--device\", choices=(\"auto\", \"cpu\"), default=\"auto\")\n    _add(parser, \"--preview-frame\", type=int)\n    _add(parser, \"--fps\", type=int)\n    _add(parser, \"--duration-sec\", type=float)\n    _add(parser, \"--physics-python\", type=Path, default=python_for(\"physics\"))\n    # Renderers without an engine switch currently implement Cycles only.\n    _add(parser, \"--engine\", choices=(\"cycles\",), default=\"cycles\")\n    if argv is None:\n        argv = sys.argv[sys.argv.index(\"--\") + 1:] if \"--\" in sys.argv else sys.argv[1:]\n    _render_args = parser.parse_args(argv)\n    # In the original CLI duration-sec is the real-time clip length. A scene's\n    # optional demo slow-motion preset must not silently multiply that request.\n    if \"--duration-sec\" in argv and \"--slow-motion\" not in argv and hasattr(_render_args, \"slow_motion\"):\n        _render_args.slow_motion = 1\n    random.seed(_render_args.seed)\n    return _render_args\n\n\ndef apply_physics_overrides(args, baseline):\n    \"\"\"Read the original {physics: ...} override format for scalar CLI scenes.\n\n    Bare schedule arrays remain accepted by the older timed-edit escape hatch.\n    Explicit scalar command-line values take precedence over the JSON defaults.\n    \"\"\"\n    path = getattr(args, \"scenario_overrides_json\", None)\n    if path is None:\n        return None\n    payload = json.loads(Path(path).read_text(encoding=\"utf-8\"))\n    if isinstance(payload, list):\n        return Path(path)\n    physics = payload.get(\"physics\", payload)\n    unknown = set(physics) - {*baseline, \"timed_edits\"}\n    if unknown:\n        raise ValueError(f\"Unknown physics overrides: {sorted(unknown)}\")\n    for name, value in physics.items():\n        if name != \"timed_edits\" and getattr(args, name, None) is None:\n            setattr(args, name, value)\n    if physics.get(\"timed_edits\"):\n        target = Path(args.out_dir) / \"timed_edits.json\"\n        target.parent.mkdir(parents=True, exist_ok=True)\n        target.write_text(json.dumps(physics[\"timed_edits\"], indent=2), encoding=\"utf-8\")\n        return target\n    return None\n\n\ndef _matrix(position, q):\n    x, y, z, w = q\n    return [[1-2*(y*y+z*z), 2*(x*y-z*w), 2*(x*z+y*w), position[0]],\n            [2*(x*y+z*w), 1-2*(x*x+z*z), 2*(y*z-x*w), position[1]],\n            [2*(x*z-y*w), 2*(y*z+x*w), 1-2*(x*x+y*y), position[2]],\n            [0, 0, 0, 1]]\n\n\ndef _optional_metrics(value):\n    if isinstance(value, dict):\n        return {key: _optional_metrics(item) for key, item in value.items()}\n    if isinstance(value, list):\n        return [_optional_metrics(item) for item in value]\n    if isinstance(value, float) and not math.isfinite(value):\n        return None\n    return value\n\n\ndef finalize_render_outputs(out: Path, scene_name: str, args, scene=None):\n    \"\"\"Keep scene-specific files and also publish the original PCVE filenames.\"\"\"\n    out = Path(out).resolve()\n    gt_path = out / \"ground_truth_transforms.json\"\n    if gt_path.is_file():\n        gt = json.loads(gt_path.read_text(encoding=\"utf-8\"))\n        gt.setdefault(\"scene\", scene_name)\n        gt.setdefault(\"schema_version\", 1)\n        camera = gt.setdefault(\"camera\", {})\n        camera.setdefault(\"resolution\", list(args.resolution))\n        camera.setdefault(\"sensor_width_mm\", 36.0)\n        if scene is not None and scene.camera is not None:\n            cam = scene.camera\n            camera.update(matrix_world=[list(row) for row in cam.matrix_world],\n                          sensor_width_mm=float(cam.data.sensor_width),\n                          sensor_fit=cam.data.sensor_fit)\n            if cam.data.type == \"ORTHO\":\n                camera.update(projection=\"orthographic\", ortho_scale=float(cam.data.ortho_scale))\n            else:\n                camera.update(projection=\"perspective\", lens_mm=float(cam.data.lens))\n        frames = gt.get(\"frames\", [])\n        # toy_car_bottle retains its raw simulation and render_frames as well.\n        rendered = gt.get(\"render_frames\", [])\n        for index, frame in enumerate(frames):\n            frame.setdefault(\"frame_index\", frame.get(\"frame\", index + 1))\n            frame.setdefault(\"time_sec\", frame.get(\"time\", index / gt.get(\"fps\", 24)))\n            if camera.get(\"matrix_world\") is not None:\n                frame.setdefault(\"camera_matrix_world\", camera[\"matrix_world\"])\n            if index < len(rendered):\n                for name, state in rendered[index].get(\"objects\", {}).items():\n                    raw = frame.get(\"objects\", {}).get(name, {})\n                    frame[name] = dict(raw, present=True, location=state[\"position\"],\n                                       quaternion_xyzw=state[\"quaternion_xyzw\"],\n                                       matrix_world=_matrix(state[\"position\"], state[\"quaternion_xyzw\"]))\n        gt.setdefault(\"frame_start\", 1)\n        gt.setdefault(\"frame_end\", len(frames))\n        if scene_name == \"toy_car_bottle\":\n            layout = gt[\"config\"][\"layout\"]\n            gt[\"objects\"] = {\n                \"car\": {\"object_name\": \"toy_car\", \"dimensions\": [layout[\"car_length\"], layout[\"car_width\"], layout[\"car_height\"]]},\n                \"bottle\": {\"object_name\": \"plastic_bottle\", \"radius\": layout[\"bottle_radius\"], \"height\": layout[\"bottle_height\"]},\n            }\n        # A short diagnostic clip may not contain an impact. Its unavailable\n        # post-contact quality measurements are null; poses must stay finite.\n        for container in (gt, gt.get(\"physics\", {})):\n            if \"quality\" in container:\n                container[\"quality\"] = _optional_metrics(container[\"quality\"])\n        for frame in frames:\n            matrices = [item[\"matrix_world\"] for item in frame.values()\n                        if isinstance(item, dict) and \"matrix_world\" in item\n                        and not (item.get(\"present\") is False and item[\"matrix_world\"] is None)]\n            matrices += [item for key, item in frame.items() if key.endswith(\"_matrix_world\")]\n            for matrix in matrices:\n                if matrix is None:\n                    raise ValueError(\"A present object must have a ground-truth transform\")\n                if not all(math.isfinite(value) for row in matrix for value in row):\n                    raise ValueError(\"Non-finite ground-truth transform\")\n        gt_path.write_text(json.dumps(gt, indent=2, ensure_ascii=False, allow_nan=False), encoding=\"utf-8\")\n    mode = getattr(args, \"mode\", \"preview\")\n    if mode == \"animation\":\n        stem = \"basketball_door\" if scene_name == \"home_basketball_door\" else scene_name\n        source = out / (stem + \".mp4\")\n        target = out / \"video.mp4\"\n        if source.is_file() and not (scene_name == \"uneven_ground_ball\" and getattr(args, \"label\", False)):\n            shutil.copy2(source, target)\n        if not target.is_file():\n            raise FileNotFoundError(f\"Animation did not produce {target}\")\n    refresh_alias = scene_name in (\"home_basketball_door\", \"pot_lid_drop\") or (\n        scene_name == \"toy_car_bottle\" and getattr(args, \"preview_frame\", None) is None)\n    if mode == \"preview\" and (refresh_alias or not (out / \"preview.png\").is_file()):\n        number = getattr(args, \"preview_frame\", None) or 1\n        candidates = [out / f\"preview_frame_{number:04d}.png\", out / \"first_frame.png\"]\n        candidates += sorted(out.glob(\"preview_frame_*.png\"))\n        source = next((p for p in candidates if p.is_file()), None)\n        if source is None:\n            raise FileNotFoundError(f\"Preview did not produce an image in {out}\")\n        shutil.copy2(source, out / \"preview.png\")\n\n\ndef run_renderer(main, scene_name):\n    global _render_args\n    _render_args = None\n    main()\n    if _render_args is not None:\n        import bpy\n        finalize_render_outputs(_render_args.out_dir, scene_name, _render_args, bpy.context.scene)\n", "pcve_blender_compat": "\"\"\"Small Blender 3.6/4.x API differences used by the scene renderers.\"\"\"\n\nSOCKET_NAMES = {\n    \"Coat Weight\": \"Clearcoat\", \"Coat Roughness\": \"Clearcoat Roughness\",\n    \"Specular IOR Level\": \"Specular\", \"Transmission Weight\": \"Transmission\",\n    \"Emission Color\": \"Emission\", \"Sheen Weight\": \"Sheen\",\n    \"Sheen Roughness\": \"Roughness\", \"Subsurface Weight\": \"Subsurface\",\n}\n\n\ndef shader_socket(node, name):\n    socket = node.inputs.get(name)\n    if socket is None:\n        socket = node.inputs.get(SOCKET_NAMES.get(name, name))\n    if socket is None:\n        raise KeyError(f\"{node.name}: missing shader input {name}\")\n    return socket\n\n\ndef set_shader_input(node, name, value):\n    socket = shader_socket(node, name)\n    if socket.type == \"VALUE\" and isinstance(value, (tuple, list)):\n        value = sum(value[:3]) / 3\n    socket.default_value = value\n\n\ndef eevee_engine():\n    import bpy\n    return \"BLENDER_EEVEE_NEXT\" if bpy.app.version >= (4, 2, 0) else \"BLENDER_EEVEE\"\n\n\ndef set_eevee_property(settings, name, value):\n    parts = name.split(\".\")\n    for part in parts[:-1]:\n        if not hasattr(settings, part):\n            return\n        settings = getattr(settings, part)\n    if hasattr(settings, parts[-1]):\n        setattr(settings, parts[-1], value)\n\n\ndef set_color_property(settings, name, value):\n    try:\n        setattr(settings, name, value)\n    except (TypeError, ValueError):\n        candidates = (\"Filmic\", \"Standard\") if name == \"view_transform\" else (\"Medium High Contrast\", \"None\")\n        for candidate in candidates:\n            try:\n                setattr(settings, name, candidate)\n                return\n            except (TypeError, ValueError):\n                continue\n        raise\n\n\ndef configure_cycles_device(bpy, scene, requested):\n    scene.cycles.device = \"CPU\"\n    scene.render.threads_mode = \"FIXED\"\n    scene.render.threads = 4\n    if requested == \"cpu\":\n        return \"CPU\"\n    prefs = bpy.context.preferences.addons[\"cycles\"].preferences\n    for backend in (\"OPTIX\", \"CUDA\", \"HIP\", \"METAL\"):\n        try:\n            prefs.compute_device_type = backend\n            prefs.get_devices()\n            found = [device for device in prefs.devices if device.type == backend]\n            if found:\n                for device in prefs.devices:\n                    device.use = device.type == backend\n                scene.cycles.device = \"GPU\"\n                return \"GPU\"\n        except (TypeError, RuntimeError, ValueError):\n            continue\n    return \"CPU\"\n", "pcve_legacy_scene": "\"\"\"Original batch/suite workflow for scenes backed by a scenario.json file.\"\"\"\n\nimport argparse\nimport hashlib\nimport importlib\nimport json\nimport random\nimport shutil\nimport subprocess\nimport time\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\n\nfrom pcve_scene_runtime import ROOT, add_build_arguments, append_render_options, render_prefix, implementation_hashes, case_outputs\n\nimport pcve_edit_dsl as dsl\n\n\nSCRIPTS = {\n    \"home_basketball_door\": (\"render_home_basketball_door.py\", \"simulate_home_basketball_door.py\"),\n    \"pot_lid_drop\": (\"render_pot_lid_drop.py\", \"simulate_pot_lid_drop.py\"),\n    \"toy_car_bottle\": (\"render_toy_car_bottle.py\", \"simulate_toy_car_bottle.py\"),\n}\n\n\ndef write_json(path, data):\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(data, indent=2, ensure_ascii=False, allow_nan=False), encoding=\"utf-8\")\n\n\ndef parser(scene, batch=False):\n    p = argparse.ArgumentParser(description=f\"Build {'randomized samples' if batch else 'a source/edit suite'} for {scene}.\")\n    p.add_argument(\"--out-root\", type=Path, default=ROOT / \"renders\" / (f\"batch_{scene}\" if batch else f\"pcve_{scene}_suite\"))\n    p.add_argument(\"--resolution\", nargs=2, type=int, default=[1280, 720])\n    p.add_argument(\"--fps\", type=int, default=24)\n    p.add_argument(\"--duration-sec\", type=float, default=4.0)\n    p.add_argument(\"--samples\", type=int, default=32)\n    p.add_argument(\"--engine\", choices=(\"cycles\",), default=\"cycles\")\n    p.add_argument(\"--mode\", choices=(\"preview\", \"animation\"), default=\"preview\" if batch else \"animation\")\n    p.add_argument(\"--skip-existing\", action=\"store_true\")\n    p.add_argument(\"--dry-run\", action=\"store_true\")\n    p.add_argument(\"--verbose-render\", action=\"store_true\")\n    p.add_argument(\"--simulate-only\", action=\"store_true\")\n    if batch:\n        p.add_argument(\"--count\", type=int, default=4)\n        p.add_argument(\"--start-index\", type=int, default=0)\n        p.add_argument(\"--seed-base\", type=int, default=7200)\n    else:\n        p.add_argument(\"--cases\", nargs=\"+\")\n        p.add_argument(\"--clean-stale-cases\", action=\"store_true\")\n    return add_build_arguments(p)\n\n\ndef scene_directory(scene):\n    candidates = (ROOT / \"clean_scripts\" / scene, ROOT / \"clean_scripts\" / scene)\n    for directory in candidates:\n        if directory.is_dir():\n            return directory\n    raise FileNotFoundError(f\"No scene directory found for {scene}: {candidates}\")\n\n\ndef command_for(scene, folder, args, seed, overrides):\n    render, simulate = SCRIPTS[scene]\n    directory = scene_directory(scene)\n    if args.simulate_only:\n        command = [str(args.physics_python), str(directory / simulate), \"--out\", str(folder / \"physics_transforms.json\")]\n    else:\n        command = render_prefix(args, directory / render)\n        command += [\"--out-dir\", str(folder), \"--mode\", args.mode,\n                    \"--resolution\", *map(str, args.resolution), \"--samples\", str(args.samples),\n                    \"--physics-python\", str(args.physics_python), \"--seed\", str(seed)]\n        append_render_options(command, args)\n    command += [\"--fps\", str(args.fps), \"--duration-sec\", str(args.duration_sec)]\n    if overrides is not None:\n        command += [\"--scenario-overrides-json\", str(overrides)]\n    return command\n\n\ndef run_case(scene, folder, args, seed, override):\n    folder = folder.resolve()\n    overrides = folder / \"scenario_overrides.json\" if override else None\n    command = command_for(scene, folder, args, seed, overrides)\n    if args.dry_run:\n        print(subprocess.list2cmdline(command))\n        return {\"status\": \"dry_run\"}\n    implementation = implementation_hashes(scene_directory(scene))\n    payload = dict(override=override, implementation=implementation, seed=seed, fps=args.fps,\n                   duration=args.duration_sec, mode=args.mode, samples=args.samples,\n                   resolution=args.resolution, engine=args.engine, device=args.device,\n                   preview_frame=args.preview_frame, simulation_only=args.simulate_only)\n    fp = hashlib.sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()\n    status_path = folder / \"run_status.json\"\n    required = [\"physics_transforms.json\"] if args.simulate_only else [\n        \"ground_truth_transforms.json\", \"scenario_metadata.json\",\n        \"video.mp4\" if args.mode == \"animation\" else \"preview.png\"]\n    if args.skip_existing and status_path.is_file():\n        previous = json.loads(status_path.read_text(encoding=\"utf-8\"))\n        if previous.get(\"fingerprint\") == fp and all((folder / p).is_file() for p in required):\n            return dict(previous, status=\"skipped_existing\")\n    if overrides is not None:\n        write_json(overrides, override)\n    folder.mkdir(parents=True, exist_ok=True)\n    start = time.perf_counter()\n    if args.verbose_render:\n        subprocess.run(command, check=True)\n    else:\n        with (folder / \"render.log\").open(\"w\", encoding=\"utf-8\") as log:\n            subprocess.run(command, stdout=log, stderr=subprocess.STDOUT, check=True)\n    for name in required:\n        if not (folder / name).is_file():\n            raise FileNotFoundError(folder / name)\n    status = dict(status=\"completed\", valid=True, fingerprint=fp, simulation_only=args.simulate_only,\n                  render_mode=args.mode, elapsed_sec=round(time.perf_counter() - start, 3),\n                  outputs=case_outputs(folder))\n    write_json(status_path, status)\n    return status\n\n\ndef batch_main(scene, argv=None):\n    args = parser(scene, batch=True).parse_args(argv)\n    args.out_root = args.out_root.resolve()\n    if args.count < 1 or args.start_index < 0:\n        raise ValueError(\"Count must be positive and start index nonnegative\")\n    directory = scene_directory(scene)\n    import sys\n    if str(directory.parent) not in sys.path:\n        sys.path.insert(0, str(directory.parent))\n    vocab = importlib.import_module(f\"{scene}.edit_vocab\").VOCAB\n    manifest = dict(schema_version=1, scene=scene, mode=args.mode, count=args.count,\n                    start_index=args.start_index, seed_base=args.seed_base, samples=[])\n    for offset in range(args.count):\n        index = args.start_index + offset\n        seed = args.seed_base + index\n        rng = random.Random(seed)\n        params = dict(vocab.baseline_physics)\n        for binding in vocab.sim_bindings.values():\n            if isinstance(binding, dsl.SimBinding) and isinstance(params[binding.key], (int, float)):\n                params[binding.key] *= rng.uniform(.8, 1.2)\n        folder = args.out_root / f\"sample_{index:04d}\"\n        result = run_case(scene, folder, args, seed, {\"physics\": params})\n        manifest[\"samples\"].append(dict(sample_index=index, seed=seed, params=params,\n                                         out_dir=str(folder), **result))\n        if not args.dry_run:\n            write_json(args.out_root / \"batch_manifest.json\", manifest)\n\n\ndef suite_main(scene, argv=None):\n    args = parser(scene).parse_args(argv)\n    args.out_root = args.out_root.resolve()\n    directory = scene_directory(scene)\n    import sys\n    if str(directory.parent) not in sys.path:\n        sys.path.insert(0, str(directory.parent))\n    module = importlib.import_module(f\"{scene}.edit_vocab\")\n    vocab = module.VOCAB\n    source_id = f\"{scene}_baseline\"\n    cases = list(module.EDIT_CASES)\n    if args.cases:\n        unknown = set(args.cases) - {source_id, *[name for name, _ in cases]}\n        if unknown:\n            raise ValueError(f\"Unknown cases: {sorted(unknown)}\")\n        cases = [(name, instruction) for name, instruction in cases if name in args.cases]\n    if args.clean_stale_cases and not args.dry_run:\n        keep = {source_id, *[name for name, _ in module.EDIT_CASES]}\n        for folder in (args.out_root / \"cases\").glob(\"*\"):\n            if folder.is_dir() and folder.name not in keep:\n                if not folder.resolve().is_relative_to(args.out_root):\n                    raise ValueError(f\"Unsafe case directory: {folder}\")\n                shutil.rmtree(folder)\n    manifest = dict(schema_version=3, suite_name=f\"pcve_{scene}_suite\", scene=scene,\n                    baseline_physics=vocab.baseline_physics, total_frames=round(args.fps * args.duration_sec),\n                    fps=args.fps, duration_sec=args.duration_sec, physical_duration_sec=args.duration_sec,\n                    playback_duration_sec=args.duration_sec, slow_motion=1, sample_fps=args.fps,\n                    samples=args.samples, resolution=args.resolution, source=None, edits=[])\n    path = args.out_root / \"suite_manifest.json\"\n    for index, (case_id, instruction) in enumerate([(source_id, None), *cases]):\n        folder = args.out_root / \"cases\" / case_id\n        record = dict(case_id=case_id, kind=\"edit\" if instruction else \"source\",\n                      case_dir=str(folder), seed=7300 + index, status=\"pending\")\n        override = None\n        if instruction:\n            edit = dsl.parse(instruction, vocab)\n            override = {\"physics\": dsl.to_scenario_override(edit, vocab)}\n            record.update(source_case_id=source_id, edit_dsl=instruction,\n                          edit_summary=\"Change the declared physical parameter and simulate the resulting rigid-body interaction.\",\n                          applies_from_frame=dsl.starts_at_frame(edit), prompts=dsl.make_prompts(edit, vocab),\n                          physics_diff={f\"{edit.property_name} ({edit.object_id})\": {\n                              \"from\": dsl.baseline_value_for(edit, vocab), \"to\": dsl.resolved_to_value(edit, vocab)},\n                              \"timing\": dsl.timing_diff(edit, vocab)})\n            manifest[\"edits\"].append(record)\n        else:\n            record[\"description\"] = module.DESCRIPTION\n            manifest[\"source\"] = record\n        if not args.dry_run:\n            prompts = dict(schema_version=2 if instruction else 1, **record)\n            if not instruction:\n                prompts[\"prompts\"] = module.DESCRIPTION\n            write_json(folder / \"prompts.json\", prompts)\n            write_json(path, manifest)\n        try:\n            record.update(run_case(scene, folder, args, record[\"seed\"], override))\n        except Exception:\n            record[\"status\"] = \"failed\"\n            write_json(path, manifest)\n            raise\n        if not args.dry_run:\n            write_json(path, manifest)\n", "pcve_render_quality": "\"\"\"Appearance render setup only; no simulation settings or shared project edits.\"\"\"\n\nimport sys\nfrom pathlib import Path\nsys.path.insert(0, str(Path(__file__).resolve().parents[2]))\nfrom pcve_blender_compat import (shader_socket, set_shader_input, eevee_engine, set_eevee_property, set_color_property)\ndef configure_renderer(bpy,scene,args):\n    scene.render.engine=eevee_engine() if args.engine=='eevee' else 'CYCLES'\n    if args.engine=='eevee':\n        set_eevee_property(scene.eevee, 'taa_render_samples', args.samples);set_eevee_property(scene.eevee, 'use_raytracing', False)\n        set_eevee_property(scene.eevee, 'ray_tracing_options.resolution_scale', '2');set_eevee_property(scene.eevee, 'ray_tracing_options.screen_trace_quality', 0.6)\n        set_eevee_property(scene.eevee, 'use_gtao', True);set_eevee_property(scene.eevee, 'gtao_distance', 0.2);set_eevee_property(scene.eevee, 'gtao_quality', 1.0)\n        set_eevee_property(scene.eevee, 'shadow_ray_count', 1);set_eevee_property(scene.eevee, 'shadow_step_count', 8)\n    else:\n        scene.cycles.samples=args.samples;scene.cycles.use_denoising=True;scene.cycles.max_bounces=8;scene.cycles.diffuse_bounces=4;scene.cycles.glossy_bounces=4\n        scene.cycles.adaptive_threshold=.008;scene.cycles.seed=19;scene.render.use_persistent_data=True\n        # Default 1.5 px pixel filter softens fine background detail; 1.0 keeps the\n        # scanned bookshelf textures crisp without aliasing the suspension threads.\n        scene.cycles.filter_width=1.0\n        scene.cycles.device='CPU'\n        if args.device=='auto':\n            prefs=bpy.context.preferences.addons['cycles'].preferences\n            try:\n                prefs.compute_device_type='CUDA';prefs.get_devices();available=[dev for dev in prefs.devices if dev.type=='CUDA']\n                for dev in prefs.devices:dev.use=(dev.type=='CUDA')\n                if available:\n                    scene.cycles.device='GPU';scene.cycles.denoiser='OPTIX' if any(dev.type=='OPTIX' for dev in prefs.devices) else 'OPENIMAGEDENOISE'\n                    print('[render] CUDA: '+', '.join(dev.name for dev in available),flush=True)\n            except Exception as exc:\n                scene.cycles.device='CPU';scene.cycles.denoiser='OPENIMAGEDENOISE'\n                print('[render] CPU fallback: '+str(exc),flush=True)\n        return scene.cycles.device\n    return 'GPU'\n\n\ndef configure_color(scene):\n    set_color_property(scene.view_settings, 'view_transform', 'AgX');set_color_property(scene.view_settings, 'look', 'AgX - Medium High Contrast');scene.view_settings.exposure=-.22\n\n\ndef prepare_eevee(bpy,scene,moving):\n    if scene.render.engine!=eevee_engine() or bpy.app.version<(4,2,0):return\n    for light in bpy.data.lights:light.use_shadow_jitter=False\n    scene.use_nodes=True;nodes=scene.node_tree.nodes;links=scene.node_tree.links;nodes.clear()\n    layers=nodes.new('CompositorNodeRLayers');denoise=nodes.new('CompositorNodeDenoise');denoise.use_hdr=True\n    composite=nodes.new('CompositorNodeComposite');links.new(layers.outputs['Image'],denoise.inputs['Image']);links.new(denoise.outputs['Image'],composite.inputs['Image'])\n    probe_data=bpy.data.lightprobes.new('Static room irradiance','VOLUME');probe_data.resolution_x=6;probe_data.resolution_y=4;probe_data.resolution_z=4;probe_data.bake_samples=32;probe_data.surfel_density=10\n    probe=bpy.data.objects.new('Static room irradiance',probe_data);scene.collection.objects.link(probe);probe.location=[.2,.5,1.3];probe.scale=[2.5,2.2,1.6]\n    dynamic=list(moving)\n    for obj in list(dynamic):dynamic.extend(obj.children_recursive)\n    dynamic=list(dict.fromkeys(dynamic));previous=[obj.hide_render for obj in dynamic]\n    try:\n        for obj in dynamic:obj.hide_render=True\n        bpy.context.view_layer.objects.active=probe;probe.select_set(True)\n        print('[render] Baking static room indirect light',flush=True);bpy.ops.object.lightprobe_cache_bake(subset='ALL')\n    finally:\n        for obj,hidden in zip(dynamic,previous):obj.hide_render=hidden\n", "scene_support": "", "scene_support.toy_car_collision.asset_import": "\"\"\"Evaluated GLB baking and wheel rig, adapted from scripts/toy_car_bottle.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport bpy\nfrom mathutils import Vector\n\ndef world_bounds(objects):\n    points=[obj.matrix_world@Vector(v) for obj in objects for v in obj.bound_box]\n    lo=Vector([min(p[i] for p in points) for i in range(3)])\n    hi=Vector([max(p[i] for p in points) for i in range(3)])\n    return lo,hi\n\n\ndef bake_parts(path):\n    \"\"\"Import a GLB and bake every mesh to world space as a standalone object.\"\"\"\n    previous=set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(path))\n    imported=[o for o in bpy.data.objects if o not in previous]\n    # Some GLBs carry turntable/NLA animations. Remove them before baking:\n    # otherwise imported scale keys override the metric size during playback.\n    for imported_obj in imported:\n        imported_obj.animation_data_clear()\n        if imported_obj.data is not None and hasattr(imported_obj.data,'animation_data_clear'):\n            imported_obj.data.animation_data_clear()\n    bpy.context.view_layer.update()\n    # Bake evaluated geometry, including the Hot Wheels armature's rest pose.\n    # Removing its rig before evaluating would collapse/skew skinned meshes.\n    depsgraph=bpy.context.evaluated_depsgraph_get()\n    parts=[]\n    for source in imported:\n        if source.type!='MESH' or not len(source.data.materials):\n            continue\n        evaluated=source.evaluated_get(depsgraph)\n        data=bpy.data.meshes.new_from_object(evaluated,preserve_all_data_layers=True,depsgraph=depsgraph)\n        data.transform(source.matrix_world)\n        part=bpy.data.objects.new(source.name+'_part',data)\n        bpy.context.collection.objects.link(part)\n        parts.append(part)\n    for source in imported:\n        if source.name in bpy.data.objects:\n            bpy.data.objects.remove(source,do_unlink=True)\n    return parts\n\n\ndef join_parts(parts,name):\n    bpy.ops.object.select_all(action='DESELECT')\n    for obj in parts:\n        obj.select_set(True)\n    bpy.context.view_layer.objects.active=parts[0]\n    bpy.ops.object.parent_clear(type='CLEAR_KEEP_TRANSFORM')\n    bpy.ops.object.transform_apply(location=True,rotation=True,scale=True)\n    if len(parts)>1:\n        bpy.ops.object.join()\n    obj=bpy.context.view_layer.objects.active\n    obj.name=name\n    bpy.context.view_layer.update()\n    return obj\n\n\ndef set_origin_to_centre(obj):\n    \"\"\"Move the origin to the object's bounding-box centre, leaving the mesh in place.\"\"\"\n    lo,hi=world_bounds([obj])\n    bpy.context.scene.cursor.location=(lo+hi)/2\n    bpy.ops.object.select_all(action='DESELECT')\n    obj.select_set(True)\n    bpy.context.view_layer.objects.active=obj\n    bpy.ops.object.origin_set(type='ORIGIN_CURSOR')\n    bpy.context.view_layer.update()\n    return lo,hi\n\n\ndef import_asset(path,name,target_axis=None,target_size=None):\n    obj=join_parts(bake_parts(path),name)\n    if target_axis is not None:\n        # Only metric-scaled assets get re-centred. Re-centring a background like the\n        # room moves its origin to the bbox centre, and the caller then sets location\n        # to room_offset, which would silently shift the whole room by -centre.\n        lo,hi=set_origin_to_centre(obj)\n        obj.location=(0,0,0)\n        factor=target_size/(hi-lo)[target_axis]\n        obj.scale=(factor,)*3\n        bpy.ops.object.transform_apply(location=False,rotation=False,scale=True)\n    bpy.context.view_layer.update()\n    return obj\n\n\nWHEEL_AXLE=(1,0,0)      # GLB width axis; the car's nose is local -Y, so this is the axle\nWHEEL_SLACK=0.02        # tolerance used to recognise a wheel pair from its bounds alone\n\n\ndef import_car(path,name,target_axis,target_size):\n    \"\"\"Import the toy car, keep the wheel pairs as separate objects and return a rig.\n\n    The rigid body in the simulation is a sliding box, so nothing here changes the\n    trajectory: the wheels are spun afterwards purely so the car does not read as\n    having its brakes locked on. Returns (rig, [(wheel_object, wheel_radius_metres)]).\n    \"\"\"\n    parts=bake_parts(path)\n    lo,hi=world_bounds(parts)\n    size=hi-lo\n    wheels,body=[],[]\n    for part in parts:\n        plo,phi=world_bounds([part])\n        ps=phi-plo\n        # A wheel pair is round in the two non-axle axes, nearly spans the car's width\n        # and sits at the bottom of the model.\n        circular=abs(ps[1]-ps[2])<=WHEEL_SLACK*max(ps[1],ps[2])\n        if circular and ps[0]>=.8*size[0] and plo[2]<=lo[2]+.15*size[2]:\n            wheels.append(part)\n        else:\n            body.append(part)\n    # The Beetle has separate tyre, rim and hub meshes for each axle.\n    # Merge coaxial pieces so each complete axle rotates about one shared pivot.\n    if len(wheels)>2:\n        groups=[]\n        for part in wheels:\n            plo,phi=world_bounds([part]);center=(plo+phi)/2\n            group=next((g for g in groups if abs(g[0]-center.y)<size.y*.025),None)\n            if group is None:groups.append([center.y,[part]])\n            else:group[1].append(part)\n        if len(groups)==2:\n            wheels=[join_parts(g[1],name+'_axle_'+str(i)) for i,g in enumerate(groups)]\n    if len(wheels)!=2:\n        # Unknown asset layout: fall back to a single mesh with no wheel spin.\n        for part in parts:\n            data=part.data\n            bpy.data.objects.remove(part,do_unlink=True)\n            bpy.data.meshes.remove(data)\n        return import_asset(path,name,target_axis,target_size),[]\n    car=join_parts(body,name)\n    radii=[]\n    for wheel in wheels:\n        wlo,whi=set_origin_to_centre(wheel)\n        radii.append((whi-wlo)[2]/2)\n    rig=bpy.data.objects.new(name+'_rig',None)\n    rig.empty_display_size=size[target_axis]*.6\n    bpy.context.collection.objects.link(rig)\n    rig.location=(lo+hi)/2\n    rig.rotation_mode='QUATERNION'\n    bpy.context.view_layer.update()\n    # Parent with keep-transform by hand: the rig may later carry location,\n    # rotation and a uniform scale, all of which must not distort the wheels.\n    inverse=rig.matrix_world.inverted()\n    for obj in [car]+wheels:\n        obj.parent=rig\n        obj.matrix_parent_inverse=inverse\n    factor=target_size/size[target_axis]\n    rig.location=(0,0,0)\n    rig.scale=(factor,)*3\n    bpy.context.view_layer.update()\n    return rig,[(wheel,radius*factor) for wheel,radius in zip(wheels,radii)]\n\n", "scene_support.toy_car_collision.cache_contract": "\"\"\"Fingerprint solver, fixed geometry, initial conditions, and sampling clock.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport hashlib\nimport json\nimport math\nfrom pathlib import Path\nfrom .scene_config import validate, SCENE_NAME\nfrom .scene_geometry import fixed_constants,KEYS\n\nfrom .runtime_support import HERE, ROOT\n\ndef simulation_signature(s):\n    import hashlib, json\n    scene_dir = _PCVE_SCENE_ROOT\n    common_dir = _PCVE_ROOT / \"clean_scripts\"\n    files = list(scene_dir.glob(\"*.py\")) + list(common_dir.glob(\"*.py\"))\n    implementation = {str(path.relative_to(_PCVE_ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n                      for path in files if path.is_file()}\n    payload = dict(implementation=implementation, scenario=s)\n    return hashlib.sha256(json.dumps(payload, sort_keys=True, allow_nan=False, default=str).encode()).hexdigest()\ndef validate_cache(d):\n    validate(d['scenario'])\n    if d.get('scene') != SCENE_NAME or d.get('schema_version') != 2: raise ValueError('Wrong cache scene/schema')\n    if d.get('simulation_signature') != simulation_signature(d['scenario']): raise ValueError('Stale cache; resimulate')\n    r=d['scenario']['render']; count=round(r['fps']*r['slow_motion']*r['duration_sec'])\n    if d['frame_end'] != count or len(d['frames']) != count or set(d['objects']) != set(KEYS): raise ValueError('Incomplete cache')\n    if not d['quality']['valid']: raise ValueError('Invalid physical trace')\n    for i,f in enumerate(d['frames']):\n        if f['frame_index'] != i+1 or abs(f['time_sec']-i/d['sample_fps']) > 1e-9: raise ValueError('Bad frame clock')\n        for key in KEYS:\n            state=f[key]\n            if state['present'] != bool(d['scenario']['physics']['present'][KEYS.index(key)]): raise ValueError('Wrong presence')\n            if state['present'] and not all(math.isfinite(v) for row in state['matrix_world'] for v in row): raise ValueError('Nonfinite transform')\n", "scene_support.toy_car_collision.runtime_support": "\"\"\"Use the established project runtime and compatibility utilities.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport sys\nfrom pathlib import Path\nimport hashlib\n\nROOT=_PCVE_ROOT\nHERE = _PCVE_SCENE_ROOT\n\nfrom pcve_scene_runtime import python_for,render_prefix,append_render_options,parse_render_args,run_renderer\n\n\ndef implementation_hashes(directory):\n    files=list(Path(directory).glob('*.py'))\n    files += [ROOT/'clean_scripts'/n for n in ('pcve_scene_runtime.py','pcve_blender_compat.py','pcve_edit_dsl.py')]\n    files += [ROOT/'scripts/pcve_render_quality.py']\n    files += [ROOT/'assets/models'/n for n in ('futuristic_room.glb','hotwheels_technetium__www.vecarz.com.glb','cartoonish_toy_car.glb')]\n    files += list((ROOT/'assets'/'polyhaven'/'toy_car_collision').glob('*.jpg'))\n    return {str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in files if p.is_file()}\n", "scene_support.toy_car_collision.scene_config": "\"\"\"SI units and independently editable toy-car initial conditions.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nfrom copy import deepcopy\nimport json\nimport math\n\nSCENE_NAME = 'toy_car_collision'\nBASELINE_PHYSICS = dict(driver_mass=.065, receiver_mass=.110, initial_velocity=.95,\n                        driver_friction=.12, receiver_friction=.14, present=[1,1])\nPHYSICS_LIMITS = dict(driver_mass=(.01,3.), receiver_mass=(.01,3.),\n                      initial_velocity=(.01,4.), driver_friction=(.001,1.), receiver_friction=(.001,1.))\nTOTAL_FRAMES = 96\n\n\ndef defaults():\n    return dict(schema_version=1, scene=SCENE_NAME, seed=0, physics=deepcopy(BASELINE_PHYSICS),\n                render=dict(fps=24, duration_sec=4., slow_motion=1, resolution=[960,540], samples=48),\n                camera=dict(location=[-.25,-1.60,.70], target=[.60,0.,.04], lens_mm=23))\n\n\ndef merge(base, overrides):\n    result = deepcopy(base)\n    if not isinstance(overrides, dict): raise ValueError('Scenario overrides must be an object')\n    for key,value in overrides.items():\n        if key not in result: raise ValueError(f'Unknown scenario field: {key}')\n        result[key] = merge(result[key],value) if isinstance(value,dict) else deepcopy(value)\n    return result\n\n\ndef finite(value):\n    return isinstance(value,(int,float)) and not isinstance(value,bool) and math.isfinite(value)\n\n\ndef validate(s):\n    if set(s) - {'schema_version','scene','physics','render','camera','seed'}:\n        raise ValueError('Unknown scenario field')\n    if s['scene'] != SCENE_NAME or s['schema_version'] != 1: raise ValueError('Wrong scene/schema')\n    if set(s['physics']) != set(BASELINE_PHYSICS): raise ValueError('Unknown editable physics parameter')\n    if s['physics']['present'] not in ([1,1],[1,0]): raise ValueError('Only receiver deletion is supported')\n    for key,(low,high) in PHYSICS_LIMITS.items():\n        if not finite(s['physics'][key]) or not low <= s['physics'][key] <= high:\n            raise ValueError(f'{key} must be finite and within {low}..{high}')\n    r=s['render']\n    if type(r['fps']) is not int or r['fps'] <= 0: raise ValueError('Invalid fps')\n    if type(r['slow_motion']) is not int or r['slow_motion'] not in (1,2,4,8) or 1440 % (r['fps']*r['slow_motion']):\n        raise ValueError('fps * slow_motion must divide the 1440 Hz simulation clock')\n    if not finite(r['duration_sec']) or not 0 < r['duration_sec'] <= 30 or round(r['fps']*r['slow_motion']*r['duration_sec']) < 2:\n        raise ValueError('Invalid duration')\n    if len(r['resolution']) != 2 or any(type(v) is not int or v <= 0 for v in r['resolution']): raise ValueError('Invalid resolution')\n    if type(r['samples']) is not int or r['samples'] < 1: raise ValueError('Invalid sample count')\n    if set(r) != {'fps','duration_sec','slow_motion','resolution','samples'}: raise ValueError('Unknown render field')\n    if set(s['camera']) != {'location','target','lens_mm'}: raise ValueError('Unknown camera field')\n    for key in ('location','target'):\n        if len(s['camera'][key]) != 3 or not all(finite(v) for v in s['camera'][key]): raise ValueError('Invalid camera vector')\n    if not finite(s['camera']['lens_mm']) or s['camera']['lens_mm'] <= 0: raise ValueError('Invalid lens')\n\n\ndef load_scenario(args):\n    s=merge(defaults(),json.loads(args.scenario_json.read_text(encoding='utf-8'))) if args.scenario_json else defaults()\n    if args.scenario_overrides_json: s=merge(s,json.loads(args.scenario_overrides_json.read_text(encoding='utf-8')))\n    for key in BASELINE_PHYSICS:\n        if getattr(args,key,None) is not None: s['physics'][key]=getattr(args,key)\n    for key in ('fps','duration_sec','slow_motion'):\n        if getattr(args,key,None) is not None: s['render'][key]=getattr(args,key)\n    validate(s)\n    return s\n\n\ndef add_scenario_arguments(parser):\n    from pathlib import Path\n    parser.add_argument('--scenario-json',type=Path)\n    parser.add_argument('--scenario-overrides-json',type=Path)\n    for key in PHYSICS_LIMITS: parser.add_argument('--'+key.replace('_','-'),type=float)\n    parser.add_argument('--fps',type=int)\n    parser.add_argument('--duration-sec',type=float)\n    parser.add_argument('--slow-motion',type=int,choices=(1,2,4,8))\n    return parser\n", "scene_support.toy_car_collision.scene_environment": "\"\"\"Locally copied furnished room and independently tinted die-cast toy cars.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport math\nfrom pathlib import Path\nfrom .scene_geometry import DIMENSIONS\nMODELS=_PCVE_ROOT/'assets'/'models'\nAPPEARANCE_VERSION='desk-bed-clear-lane-two-distinct-toys-v2'\nROOM_ASSET='futuristic_room.glb'\nCAR_ASSET='hotwheels_technetium__www.vecarz.com.glb'\nRECEIVER_ASSET='cartoonish_toy_car.glb'\nCAR_ASSETS=(CAR_ASSET,RECEIVER_ASSET)\nROOM_ORIGIN=(-2.0,.82,.05)\nROOM_YAW=0.\n\ndef build_environment(bpy,scene):\n    from mathutils import Vector,Matrix\n    transform=Matrix.Rotation(ROOM_YAW,4,'Z')@Matrix.Translation(-Vector(ROOM_ORIGIN))\n    before=set(bpy.data.objects);bpy.ops.import_scene.gltf(filepath=str(MODELS/ROOM_ASSET))\n    bpy.context.view_layer.update()\n    for o in set(bpy.data.objects)-before:\n        o.animation_data_clear()\n        if o.type in ('LIGHT','CAMERA') or o.name.startswith(('Ammobox','Books.001_','Books.006_','ChineseSoldier','OfficeChair_')):\n            bpy.data.objects.remove(o,do_unlink=True);continue\n        if o.parent is None:o.matrix_world=transform@o.matrix_world\n    for m in bpy.data.materials:\n        if not m.use_nodes:continue\n        for n in m.node_tree.nodes:\n            if n.type=='BSDF_PRINCIPLED' and n.inputs.get('Emission Strength'):n.inputs['Emission Strength'].default_value=0\n    world=bpy.data.worlds.new('Soft apartment ambient');world.use_nodes=True;scene.world=world\n    world.node_tree.nodes['Background'].inputs['Color'].default_value=(.45,.55,.7,1)\n    world.node_tree.nodes['Background'].inputs['Strength'].default_value=.22\n    for name,loc,power,size,color in [('Broad window',(-.4,-.9,2.4),180,2.,(1.,.91,.78)),('Cool room bounce',(2.,1.,2.2),120,1.8,(.78,.86,1.))]:\n        bpy.ops.object.light_add(type='AREA',location=loc);o=bpy.context.object;o.name=name\n        o.data.energy=power;o.data.shape='DISK';o.data.size=size;o.data.color=color\n        o.rotation_euler=(Vector((.7,0,0))-o.location).to_track_quat('-Z','Y').to_euler()\n\ndef make_cars(bpy,present):\n    from .asset_import import import_car\n    objects={};wheels={}\n    for i,key in enumerate(('car_a','car_b')):\n        if not present[i]:continue\n        root,spin=import_car(MODELS/CAR_ASSETS[i],key,1,DIMENSIONS[i][0])\n        physics=bpy.data.objects.new(key+'_physics',None);bpy.context.collection.objects.link(physics)\n        root.parent=physics;root.rotation_mode='XYZ';root.rotation_euler=(0,0,math.pi/2)\n        for part in root.children_recursive:\n            if part.type!='MESH':continue\n            for slot in part.material_slots:\n                m=slot.material\n                if not m:continue\n                if i==1:\n                    if m.use_nodes:\n                        shader=m.node_tree.nodes.get('Principled BSDF')\n                        if shader and 'Material.002' in m.name:\n                            shader.inputs['Base Color'].default_value=(.025,.22,.31,1)\n                            shader.inputs['Roughness'].default_value=.3\n                            if shader.inputs.get('Coat Weight'):shader.inputs['Coat Weight'].default_value=.35\n                    continue\n                if 'Livery' not in m.name:continue\n                mat=m.copy();mat.name=key+'_paint';slot.material=mat\n                n=mat.node_tree.nodes;l=mat.node_tree.links;bs=n.get('Principled BSDF');base=bs.inputs['Base Color'];links=list(base.links)\n                if links:\n                    source=links[0].from_socket;l.remove(links[0]);mix=n.new('ShaderNodeMixRGB');mix.blend_type='MULTIPLY'\n                    mix.inputs[0].default_value=.78;mix.inputs[2].default_value=((.95,.15,.045,1) if i==0 else (.07,.36,.95,1))\n                    l.new(source,mix.inputs[1]);l.new(mix.outputs[0],base)\n                bs.inputs['Metallic'].default_value=.72;bs.inputs['Roughness'].default_value=.24\n                if bs.inputs.get('Coat Weight'):bs.inputs['Coat Weight'].default_value=.35\n        objects[key]=physics;wheels[key]=spin\n    return objects,wheels\n", "scene_support.toy_car_collision.scene_geometry": "\"\"\"Metric dimensions, collision proxy and deterministic simulation clock.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nKEYS=('car_a','car_b')\n# Visual bounds at the chosen model scale: length, width, height in metres.\nDIMENSIONS=((.145,.145*189.85845947265625/363.76861572265625,.145*138.92532423161902/363.76861572265625),\n            (.180,.180*4.010020732879639/7.570144176483154,.180*3.5043145418167114/7.570144176483154))\nHALF_EXTENTS=tuple(tuple(v/2 for v in size) for size in DIMENSIONS)\nSTART_X=(-.42,0.)\nSIM_HZ=1440\nFLOOR_FRICTION=.5\n\ndef fixed_constants():\n    return dict(dimensions=DIMENSIONS,half_extents=HALF_EXTENTS,start_x=START_X,sim_hz=SIM_HZ,\n                floor_friction=FLOOR_FRICTION,gravity=9.81,pair_restitution=.32,\n                proxy='free 6-DOF rigid box; effective rolling drag at floor; visual wheels roll by travelled arc length')\n", "scene_support.toy_car_collision": "\"\"\"Toy car to toy car momentum transfer in an imported furnished room.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n", "asset_import": "\"\"\"Evaluated GLB baking and wheel rig, adapted from scripts/toy_car_bottle.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport bpy\nfrom mathutils import Vector\n\ndef world_bounds(objects):\n    points=[obj.matrix_world@Vector(v) for obj in objects for v in obj.bound_box]\n    lo=Vector([min(p[i] for p in points) for i in range(3)])\n    hi=Vector([max(p[i] for p in points) for i in range(3)])\n    return lo,hi\n\n\ndef bake_parts(path):\n    \"\"\"Import a GLB and bake every mesh to world space as a standalone object.\"\"\"\n    previous=set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(path))\n    imported=[o for o in bpy.data.objects if o not in previous]\n    # Some GLBs carry turntable/NLA animations. Remove them before baking:\n    # otherwise imported scale keys override the metric size during playback.\n    for imported_obj in imported:\n        imported_obj.animation_data_clear()\n        if imported_obj.data is not None and hasattr(imported_obj.data,'animation_data_clear'):\n            imported_obj.data.animation_data_clear()\n    bpy.context.view_layer.update()\n    # Bake evaluated geometry, including the Hot Wheels armature's rest pose.\n    # Removing its rig before evaluating would collapse/skew skinned meshes.\n    depsgraph=bpy.context.evaluated_depsgraph_get()\n    parts=[]\n    for source in imported:\n        if source.type!='MESH' or not len(source.data.materials):\n            continue\n        evaluated=source.evaluated_get(depsgraph)\n        data=bpy.data.meshes.new_from_object(evaluated,preserve_all_data_layers=True,depsgraph=depsgraph)\n        data.transform(source.matrix_world)\n        part=bpy.data.objects.new(source.name+'_part',data)\n        bpy.context.collection.objects.link(part)\n        parts.append(part)\n    for source in imported:\n        if source.name in bpy.data.objects:\n            bpy.data.objects.remove(source,do_unlink=True)\n    return parts\n\n\ndef join_parts(parts,name):\n    bpy.ops.object.select_all(action='DESELECT')\n    for obj in parts:\n        obj.select_set(True)\n    bpy.context.view_layer.objects.active=parts[0]\n    bpy.ops.object.parent_clear(type='CLEAR_KEEP_TRANSFORM')\n    bpy.ops.object.transform_apply(location=True,rotation=True,scale=True)\n    if len(parts)>1:\n        bpy.ops.object.join()\n    obj=bpy.context.view_layer.objects.active\n    obj.name=name\n    bpy.context.view_layer.update()\n    return obj\n\n\ndef set_origin_to_centre(obj):\n    \"\"\"Move the origin to the object's bounding-box centre, leaving the mesh in place.\"\"\"\n    lo,hi=world_bounds([obj])\n    bpy.context.scene.cursor.location=(lo+hi)/2\n    bpy.ops.object.select_all(action='DESELECT')\n    obj.select_set(True)\n    bpy.context.view_layer.objects.active=obj\n    bpy.ops.object.origin_set(type='ORIGIN_CURSOR')\n    bpy.context.view_layer.update()\n    return lo,hi\n\n\ndef import_asset(path,name,target_axis=None,target_size=None):\n    obj=join_parts(bake_parts(path),name)\n    if target_axis is not None:\n        # Only metric-scaled assets get re-centred. Re-centring a background like the\n        # room moves its origin to the bbox centre, and the caller then sets location\n        # to room_offset, which would silently shift the whole room by -centre.\n        lo,hi=set_origin_to_centre(obj)\n        obj.location=(0,0,0)\n        factor=target_size/(hi-lo)[target_axis]\n        obj.scale=(factor,)*3\n        bpy.ops.object.transform_apply(location=False,rotation=False,scale=True)\n    bpy.context.view_layer.update()\n    return obj\n\n\nWHEEL_AXLE=(1,0,0)      # GLB width axis; the car's nose is local -Y, so this is the axle\nWHEEL_SLACK=0.02        # tolerance used to recognise a wheel pair from its bounds alone\n\n\ndef import_car(path,name,target_axis,target_size):\n    \"\"\"Import the toy car, keep the wheel pairs as separate objects and return a rig.\n\n    The rigid body in the simulation is a sliding box, so nothing here changes the\n    trajectory: the wheels are spun afterwards purely so the car does not read as\n    having its brakes locked on. Returns (rig, [(wheel_object, wheel_radius_metres)]).\n    \"\"\"\n    parts=bake_parts(path)\n    lo,hi=world_bounds(parts)\n    size=hi-lo\n    wheels,body=[],[]\n    for part in parts:\n        plo,phi=world_bounds([part])\n        ps=phi-plo\n        # A wheel pair is round in the two non-axle axes, nearly spans the car's width\n        # and sits at the bottom of the model.\n        circular=abs(ps[1]-ps[2])<=WHEEL_SLACK*max(ps[1],ps[2])\n        if circular and ps[0]>=.8*size[0] and plo[2]<=lo[2]+.15*size[2]:\n            wheels.append(part)\n        else:\n            body.append(part)\n    # The Beetle has separate tyre, rim and hub meshes for each axle.\n    # Merge coaxial pieces so each complete axle rotates about one shared pivot.\n    if len(wheels)>2:\n        groups=[]\n        for part in wheels:\n            plo,phi=world_bounds([part]);center=(plo+phi)/2\n            group=next((g for g in groups if abs(g[0]-center.y)<size.y*.025),None)\n            if group is None:groups.append([center.y,[part]])\n            else:group[1].append(part)\n        if len(groups)==2:\n            wheels=[join_parts(g[1],name+'_axle_'+str(i)) for i,g in enumerate(groups)]\n    if len(wheels)!=2:\n        # Unknown asset layout: fall back to a single mesh with no wheel spin.\n        for part in parts:\n            data=part.data\n            bpy.data.objects.remove(part,do_unlink=True)\n            bpy.data.meshes.remove(data)\n        return import_asset(path,name,target_axis,target_size),[]\n    car=join_parts(body,name)\n    radii=[]\n    for wheel in wheels:\n        wlo,whi=set_origin_to_centre(wheel)\n        radii.append((whi-wlo)[2]/2)\n    rig=bpy.data.objects.new(name+'_rig',None)\n    rig.empty_display_size=size[target_axis]*.6\n    bpy.context.collection.objects.link(rig)\n    rig.location=(lo+hi)/2\n    rig.rotation_mode='QUATERNION'\n    bpy.context.view_layer.update()\n    # Parent with keep-transform by hand: the rig may later carry location,\n    # rotation and a uniform scale, all of which must not distort the wheels.\n    inverse=rig.matrix_world.inverted()\n    for obj in [car]+wheels:\n        obj.parent=rig\n        obj.matrix_parent_inverse=inverse\n    factor=target_size/size[target_axis]\n    rig.location=(0,0,0)\n    rig.scale=(factor,)*3\n    bpy.context.view_layer.update()\n    return rig,[(wheel,radius*factor) for wheel,radius in zip(wheels,radii)]\n\n", "cache_contract": "\"\"\"Fingerprint solver, fixed geometry, initial conditions, and sampling clock.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport hashlib\nimport json\nimport math\nfrom pathlib import Path\nfrom .scene_config import validate, SCENE_NAME\nfrom .scene_geometry import fixed_constants,KEYS\n\nfrom .runtime_support import HERE, ROOT\n\ndef simulation_signature(s):\n    import hashlib, json\n    scene_dir = _PCVE_SCENE_ROOT\n    common_dir = _PCVE_ROOT / \"clean_scripts\"\n    files = list(scene_dir.glob(\"*.py\")) + list(common_dir.glob(\"*.py\"))\n    implementation = {str(path.relative_to(_PCVE_ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n                      for path in files if path.is_file()}\n    payload = dict(implementation=implementation, scenario=s)\n    return hashlib.sha256(json.dumps(payload, sort_keys=True, allow_nan=False, default=str).encode()).hexdigest()\ndef validate_cache(d):\n    validate(d['scenario'])\n    if d.get('scene') != SCENE_NAME or d.get('schema_version') != 2: raise ValueError('Wrong cache scene/schema')\n    if d.get('simulation_signature') != simulation_signature(d['scenario']): raise ValueError('Stale cache; resimulate')\n    r=d['scenario']['render']; count=round(r['fps']*r['slow_motion']*r['duration_sec'])\n    if d['frame_end'] != count or len(d['frames']) != count or set(d['objects']) != set(KEYS): raise ValueError('Incomplete cache')\n    if not d['quality']['valid']: raise ValueError('Invalid physical trace')\n    for i,f in enumerate(d['frames']):\n        if f['frame_index'] != i+1 or abs(f['time_sec']-i/d['sample_fps']) > 1e-9: raise ValueError('Bad frame clock')\n        for key in KEYS:\n            state=f[key]\n            if state['present'] != bool(d['scenario']['physics']['present'][KEYS.index(key)]): raise ValueError('Wrong presence')\n            if state['present'] and not all(math.isfinite(v) for row in state['matrix_world'] for v in row): raise ValueError('Nonfinite transform')\n", "runtime_support": "\"\"\"Use the established project runtime and compatibility utilities.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport sys\nfrom pathlib import Path\nimport hashlib\n\nROOT=_PCVE_ROOT\nHERE = _PCVE_SCENE_ROOT\n\nfrom pcve_scene_runtime import python_for,render_prefix,append_render_options,parse_render_args,run_renderer\n\n\ndef implementation_hashes(directory):\n    files=list(Path(directory).glob('*.py'))\n    files += [ROOT/'clean_scripts'/n for n in ('pcve_scene_runtime.py','pcve_blender_compat.py','pcve_edit_dsl.py')]\n    files += [ROOT/'scripts/pcve_render_quality.py']\n    files += [ROOT/'assets/models'/n for n in ('futuristic_room.glb','hotwheels_technetium__www.vecarz.com.glb','cartoonish_toy_car.glb')]\n    files += list((ROOT/'assets'/'polyhaven'/'toy_car_collision').glob('*.jpg'))\n    return {str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in files if p.is_file()}\n", "scene_config": "\"\"\"SI units and independently editable toy-car initial conditions.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nfrom copy import deepcopy\nimport json\nimport math\n\nSCENE_NAME = 'toy_car_collision'\nBASELINE_PHYSICS = dict(driver_mass=.065, receiver_mass=.110, initial_velocity=.95,\n                        driver_friction=.12, receiver_friction=.14, receiver_speed_multiplier=1.,\n                        present=[1,1])\nPHYSICS_LIMITS = dict(driver_mass=(.01,3.), receiver_mass=(.01,3.),\n                      initial_velocity=(.01,4.), driver_friction=(.001,1.), receiver_friction=(.001,1.))\nTOTAL_FRAMES = 96\n\n\ndef defaults():\n    return dict(schema_version=1, scene=SCENE_NAME, seed=0, physics=deepcopy(BASELINE_PHYSICS),\n                render=dict(fps=24, duration_sec=4., slow_motion=1, resolution=[960,540], samples=48),\n                camera=dict(location=[-.25,-1.60,.70], target=[.60,0.,.04], lens_mm=23))\n\n\ndef merge(base, overrides):\n    result = deepcopy(base)\n    if not isinstance(overrides, dict): raise ValueError('Scenario overrides must be an object')\n    for key,value in overrides.items():\n        if key not in result: raise ValueError(f'Unknown scenario field: {key}')\n        result[key] = merge(result[key],value) if isinstance(value,dict) else deepcopy(value)\n    return result\n\n\ndef finite(value):\n    return isinstance(value,(int,float)) and not isinstance(value,bool) and math.isfinite(value)\n\n\ndef validate(s):\n    if set(s) - {'schema_version','scene','physics','render','camera','seed'}:\n        raise ValueError('Unknown scenario field')\n    if s['scene'] != SCENE_NAME or s['schema_version'] != 1: raise ValueError('Wrong scene/schema')\n    if set(s['physics']) != set(BASELINE_PHYSICS): raise ValueError('Unknown editable physics parameter')\n    if s['physics']['present'] not in ([1,1],[1,0]): raise ValueError('Only receiver deletion is supported')\n    for key,(low,high) in PHYSICS_LIMITS.items():\n        if not finite(s['physics'][key]) or not low <= s['physics'][key] <= high:\n            raise ValueError(f'{key} must be finite and within {low}..{high}')\n    if s['physics']['receiver_speed_multiplier'] != 1.:\n        raise ValueError('receiver_speed_multiplier is a mid-run knob; write it as '\n                         'SET car_b.speed ... AT FRAME n, not as a whole-clip override')\n    r=s['render']\n    if type(r['fps']) is not int or r['fps'] <= 0: raise ValueError('Invalid fps')\n    if type(r['slow_motion']) is not int or r['slow_motion'] not in (1,2,4,8) or 1440 % (r['fps']*r['slow_motion']):\n        raise ValueError('fps * slow_motion must divide the 1440 Hz simulation clock')\n    if not finite(r['duration_sec']) or not 0 < r['duration_sec'] <= 30 or round(r['fps']*r['slow_motion']*r['duration_sec']) < 2:\n        raise ValueError('Invalid duration')\n    if len(r['resolution']) != 2 or any(type(v) is not int or v <= 0 for v in r['resolution']): raise ValueError('Invalid resolution')\n    if type(r['samples']) is not int or r['samples'] < 1: raise ValueError('Invalid sample count')\n    if set(r) != {'fps','duration_sec','slow_motion','resolution','samples'}: raise ValueError('Unknown render field')\n    if set(s['camera']) != {'location','target','lens_mm'}: raise ValueError('Unknown camera field')\n    for key in ('location','target'):\n        if len(s['camera'][key]) != 3 or not all(finite(v) for v in s['camera'][key]): raise ValueError('Invalid camera vector')\n    if not finite(s['camera']['lens_mm']) or s['camera']['lens_mm'] <= 0: raise ValueError('Invalid lens')\n\n\ndef load_scenario(args):\n    s=merge(defaults(),json.loads(args.scenario_json.read_text(encoding='utf-8'))) if args.scenario_json else defaults()\n    if args.scenario_overrides_json: s=merge(s,json.loads(args.scenario_overrides_json.read_text(encoding='utf-8')))\n    for key in BASELINE_PHYSICS:\n        if getattr(args,key,None) is not None: s['physics'][key]=getattr(args,key)\n    for key in ('fps','duration_sec','slow_motion'):\n        if getattr(args,key,None) is not None: s['render'][key]=getattr(args,key)\n    validate(s)\n    return s\n\n\ndef add_scenario_arguments(parser):\n    from pathlib import Path\n    parser.add_argument('--scenario-json',type=Path)\n    parser.add_argument('--scenario-overrides-json',type=Path)\n    for key in PHYSICS_LIMITS: parser.add_argument('--'+key.replace('_','-'),type=float)\n    parser.add_argument('--fps',type=int)\n    parser.add_argument('--duration-sec',type=float)\n    parser.add_argument('--slow-motion',type=int,choices=(1,2,4,8))\n    return parser\n", "scene_environment": "\"\"\"Locally copied furnished room and independently tinted die-cast toy cars.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport math\nfrom pathlib import Path\nfrom .scene_geometry import DIMENSIONS\nMODELS=_PCVE_ROOT/'assets'/'models'\nAPPEARANCE_VERSION='desk-bed-clear-lane-two-distinct-toys-v2'\nROOM_ASSET='futuristic_room.glb'\nCAR_ASSET='hotwheels_technetium__www.vecarz.com.glb'\nRECEIVER_ASSET='cartoonish_toy_car.glb'\nCAR_ASSETS=(CAR_ASSET,RECEIVER_ASSET)\nROOM_ORIGIN=(-2.0,.82,.05)\nROOM_YAW=0.\n\ndef build_environment(bpy,scene):\n    from mathutils import Vector,Matrix\n    transform=Matrix.Rotation(ROOM_YAW,4,'Z')@Matrix.Translation(-Vector(ROOM_ORIGIN))\n    before=set(bpy.data.objects);bpy.ops.import_scene.gltf(filepath=str(MODELS/ROOM_ASSET))\n    bpy.context.view_layer.update()\n    for o in set(bpy.data.objects)-before:\n        o.animation_data_clear()\n        if o.type in ('LIGHT','CAMERA') or o.name.startswith(('Ammobox','Books.001_','Books.006_','ChineseSoldier','OfficeChair_')):\n            bpy.data.objects.remove(o,do_unlink=True);continue\n        if o.parent is None:o.matrix_world=transform@o.matrix_world\n    for m in bpy.data.materials:\n        if not m.use_nodes:continue\n        for n in m.node_tree.nodes:\n            if n.type=='BSDF_PRINCIPLED' and n.inputs.get('Emission Strength'):n.inputs['Emission Strength'].default_value=0\n    world=bpy.data.worlds.new('Soft apartment ambient');world.use_nodes=True;scene.world=world\n    world.node_tree.nodes['Background'].inputs['Color'].default_value=(.45,.55,.7,1)\n    world.node_tree.nodes['Background'].inputs['Strength'].default_value=.22\n    for name,loc,power,size,color in [('Broad window',(-.4,-.9,2.4),180,2.,(1.,.91,.78)),('Cool room bounce',(2.,1.,2.2),120,1.8,(.78,.86,1.))]:\n        bpy.ops.object.light_add(type='AREA',location=loc);o=bpy.context.object;o.name=name\n        o.data.energy=power;o.data.shape='DISK';o.data.size=size;o.data.color=color\n        o.rotation_euler=(Vector((.7,0,0))-o.location).to_track_quat('-Z','Y').to_euler()\n\ndef make_cars(bpy,present):\n    from .asset_import import import_car\n    objects={};wheels={}\n    for i,key in enumerate(('car_a','car_b')):\n        if not present[i]:continue\n        root,spin=import_car(MODELS/CAR_ASSETS[i],key,1,DIMENSIONS[i][0])\n        physics=bpy.data.objects.new(key+'_physics',None);bpy.context.collection.objects.link(physics)\n        root.parent=physics;root.rotation_mode='XYZ';root.rotation_euler=(0,0,math.pi/2)\n        for part in root.children_recursive:\n            if part.type!='MESH':continue\n            for slot in part.material_slots:\n                m=slot.material\n                if not m:continue\n                if i==1:\n                    if m.use_nodes:\n                        shader=m.node_tree.nodes.get('Principled BSDF')\n                        if shader and 'Material.002' in m.name:\n                            shader.inputs['Base Color'].default_value=(.025,.22,.31,1)\n                            shader.inputs['Roughness'].default_value=.3\n                            if shader.inputs.get('Coat Weight'):shader.inputs['Coat Weight'].default_value=.35\n                    continue\n                if 'Livery' not in m.name:continue\n                mat=m.copy();mat.name=key+'_paint';slot.material=mat\n                n=mat.node_tree.nodes;l=mat.node_tree.links;bs=n.get('Principled BSDF');base=bs.inputs['Base Color'];links=list(base.links)\n                if links:\n                    source=links[0].from_socket;l.remove(links[0]);mix=n.new('ShaderNodeMixRGB');mix.blend_type='MULTIPLY'\n                    mix.inputs[0].default_value=.78;mix.inputs[2].default_value=((.95,.15,.045,1) if i==0 else (.07,.36,.95,1))\n                    l.new(source,mix.inputs[1]);l.new(mix.outputs[0],base)\n                bs.inputs['Metallic'].default_value=.72;bs.inputs['Roughness'].default_value=.24\n                if bs.inputs.get('Coat Weight'):bs.inputs['Coat Weight'].default_value=.35\n        objects[key]=physics;wheels[key]=spin\n    return objects,wheels\n", "scene_geometry": "\"\"\"Metric dimensions, collision proxy and deterministic simulation clock.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nKEYS=('car_a','car_b')\n# Visual bounds at the chosen model scale: length, width, height in metres.\nDIMENSIONS=((.145,.145*189.85845947265625/363.76861572265625,.145*138.92532423161902/363.76861572265625),\n            (.180,.180*4.010020732879639/7.570144176483154,.180*3.5043145418167114/7.570144176483154))\nHALF_EXTENTS=tuple(tuple(v/2 for v in size) for size in DIMENSIONS)\nSTART_X=(-.42,0.)\nSIM_HZ=1440\nFLOOR_FRICTION=.5\n\ndef fixed_constants():\n    return dict(dimensions=DIMENSIONS,half_extents=HALF_EXTENTS,start_x=START_X,sim_hz=SIM_HZ,\n                floor_friction=FLOOR_FRICTION,gravity=9.81,pair_restitution=.32,\n                proxy='free 6-DOF rigid box; effective rolling drag at floor; visual wheels roll by travelled arc length')\n", "toy_car_collision.asset_import": "\"\"\"Evaluated GLB baking and wheel rig, adapted from scripts/toy_car_bottle.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport bpy\nfrom mathutils import Vector\n\ndef world_bounds(objects):\n    points=[obj.matrix_world@Vector(v) for obj in objects for v in obj.bound_box]\n    lo=Vector([min(p[i] for p in points) for i in range(3)])\n    hi=Vector([max(p[i] for p in points) for i in range(3)])\n    return lo,hi\n\n\ndef bake_parts(path):\n    \"\"\"Import a GLB and bake every mesh to world space as a standalone object.\"\"\"\n    previous=set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(path))\n    imported=[o for o in bpy.data.objects if o not in previous]\n    # Some GLBs carry turntable/NLA animations. Remove them before baking:\n    # otherwise imported scale keys override the metric size during playback.\n    for imported_obj in imported:\n        imported_obj.animation_data_clear()\n        if imported_obj.data is not None and hasattr(imported_obj.data,'animation_data_clear'):\n            imported_obj.data.animation_data_clear()\n    bpy.context.view_layer.update()\n    # Bake evaluated geometry, including the Hot Wheels armature's rest pose.\n    # Removing its rig before evaluating would collapse/skew skinned meshes.\n    depsgraph=bpy.context.evaluated_depsgraph_get()\n    parts=[]\n    for source in imported:\n        if source.type!='MESH' or not len(source.data.materials):\n            continue\n        evaluated=source.evaluated_get(depsgraph)\n        data=bpy.data.meshes.new_from_object(evaluated,preserve_all_data_layers=True,depsgraph=depsgraph)\n        data.transform(source.matrix_world)\n        part=bpy.data.objects.new(source.name+'_part',data)\n        bpy.context.collection.objects.link(part)\n        parts.append(part)\n    for source in imported:\n        if source.name in bpy.data.objects:\n            bpy.data.objects.remove(source,do_unlink=True)\n    return parts\n\n\ndef join_parts(parts,name):\n    bpy.ops.object.select_all(action='DESELECT')\n    for obj in parts:\n        obj.select_set(True)\n    bpy.context.view_layer.objects.active=parts[0]\n    bpy.ops.object.parent_clear(type='CLEAR_KEEP_TRANSFORM')\n    bpy.ops.object.transform_apply(location=True,rotation=True,scale=True)\n    if len(parts)>1:\n        bpy.ops.object.join()\n    obj=bpy.context.view_layer.objects.active\n    obj.name=name\n    bpy.context.view_layer.update()\n    return obj\n\n\ndef set_origin_to_centre(obj):\n    \"\"\"Move the origin to the object's bounding-box centre, leaving the mesh in place.\"\"\"\n    lo,hi=world_bounds([obj])\n    bpy.context.scene.cursor.location=(lo+hi)/2\n    bpy.ops.object.select_all(action='DESELECT')\n    obj.select_set(True)\n    bpy.context.view_layer.objects.active=obj\n    bpy.ops.object.origin_set(type='ORIGIN_CURSOR')\n    bpy.context.view_layer.update()\n    return lo,hi\n\n\ndef import_asset(path,name,target_axis=None,target_size=None):\n    obj=join_parts(bake_parts(path),name)\n    if target_axis is not None:\n        # Only metric-scaled assets get re-centred. Re-centring a background like the\n        # room moves its origin to the bbox centre, and the caller then sets location\n        # to room_offset, which would silently shift the whole room by -centre.\n        lo,hi=set_origin_to_centre(obj)\n        obj.location=(0,0,0)\n        factor=target_size/(hi-lo)[target_axis]\n        obj.scale=(factor,)*3\n        bpy.ops.object.transform_apply(location=False,rotation=False,scale=True)\n    bpy.context.view_layer.update()\n    return obj\n\n\nWHEEL_AXLE=(1,0,0)      # GLB width axis; the car's nose is local -Y, so this is the axle\nWHEEL_SLACK=0.02        # tolerance used to recognise a wheel pair from its bounds alone\n\n\ndef import_car(path,name,target_axis,target_size):\n    \"\"\"Import the toy car, keep the wheel pairs as separate objects and return a rig.\n\n    The rigid body in the simulation is a sliding box, so nothing here changes the\n    trajectory: the wheels are spun afterwards purely so the car does not read as\n    having its brakes locked on. Returns (rig, [(wheel_object, wheel_radius_metres)]).\n    \"\"\"\n    parts=bake_parts(path)\n    lo,hi=world_bounds(parts)\n    size=hi-lo\n    wheels,body=[],[]\n    for part in parts:\n        plo,phi=world_bounds([part])\n        ps=phi-plo\n        # A wheel pair is round in the two non-axle axes, nearly spans the car's width\n        # and sits at the bottom of the model.\n        circular=abs(ps[1]-ps[2])<=WHEEL_SLACK*max(ps[1],ps[2])\n        if circular and ps[0]>=.8*size[0] and plo[2]<=lo[2]+.15*size[2]:\n            wheels.append(part)\n        else:\n            body.append(part)\n    # The Beetle has separate tyre, rim and hub meshes for each axle.\n    # Merge coaxial pieces so each complete axle rotates about one shared pivot.\n    if len(wheels)>2:\n        groups=[]\n        for part in wheels:\n            plo,phi=world_bounds([part]);center=(plo+phi)/2\n            group=next((g for g in groups if abs(g[0]-center.y)<size.y*.025),None)\n            if group is None:groups.append([center.y,[part]])\n            else:group[1].append(part)\n        if len(groups)==2:\n            wheels=[join_parts(g[1],name+'_axle_'+str(i)) for i,g in enumerate(groups)]\n    if len(wheels)!=2:\n        # Unknown asset layout: fall back to a single mesh with no wheel spin.\n        for part in parts:\n            data=part.data\n            bpy.data.objects.remove(part,do_unlink=True)\n            bpy.data.meshes.remove(data)\n        return import_asset(path,name,target_axis,target_size),[]\n    car=join_parts(body,name)\n    radii=[]\n    for wheel in wheels:\n        wlo,whi=set_origin_to_centre(wheel)\n        radii.append((whi-wlo)[2]/2)\n    rig=bpy.data.objects.new(name+'_rig',None)\n    rig.empty_display_size=size[target_axis]*.6\n    bpy.context.collection.objects.link(rig)\n    rig.location=(lo+hi)/2\n    rig.rotation_mode='QUATERNION'\n    bpy.context.view_layer.update()\n    # Parent with keep-transform by hand: the rig may later carry location,\n    # rotation and a uniform scale, all of which must not distort the wheels.\n    inverse=rig.matrix_world.inverted()\n    for obj in [car]+wheels:\n        obj.parent=rig\n        obj.matrix_parent_inverse=inverse\n    factor=target_size/size[target_axis]\n    rig.location=(0,0,0)\n    rig.scale=(factor,)*3\n    bpy.context.view_layer.update()\n    return rig,[(wheel,radius*factor) for wheel,radius in zip(wheels,radii)]\n\n", "toy_car_collision.cache_contract": "\"\"\"Fingerprint solver, fixed geometry, initial conditions, and sampling clock.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport hashlib\nimport json\nimport math\nfrom pathlib import Path\nfrom .scene_config import validate, SCENE_NAME\nfrom .scene_geometry import fixed_constants,KEYS\n\nfrom .runtime_support import HERE, ROOT\n\ndef simulation_signature(s):\n    import hashlib, json\n    scene_dir = _PCVE_SCENE_ROOT\n    common_dir = _PCVE_ROOT / \"clean_scripts\"\n    files = list(scene_dir.glob(\"*.py\")) + list(common_dir.glob(\"*.py\"))\n    implementation = {str(path.relative_to(_PCVE_ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n                      for path in files if path.is_file()}\n    payload = dict(implementation=implementation, scenario=s)\n    return hashlib.sha256(json.dumps(payload, sort_keys=True, allow_nan=False, default=str).encode()).hexdigest()\ndef validate_cache(d):\n    validate(d['scenario'])\n    if d.get('scene') != SCENE_NAME or d.get('schema_version') != 2: raise ValueError('Wrong cache scene/schema')\n    if d.get('simulation_signature') != simulation_signature(d['scenario']): raise ValueError('Stale cache; resimulate')\n    r=d['scenario']['render']; count=round(r['fps']*r['slow_motion']*r['duration_sec'])\n    if d['frame_end'] != count or len(d['frames']) != count or set(d['objects']) != set(KEYS): raise ValueError('Incomplete cache')\n    if not d['quality']['valid']: raise ValueError('Invalid physical trace')\n    for i,f in enumerate(d['frames']):\n        if f['frame_index'] != i+1 or abs(f['time_sec']-i/d['sample_fps']) > 1e-9: raise ValueError('Bad frame clock')\n        for key in KEYS:\n            state=f[key]\n            if state['present'] != bool(d['scenario']['physics']['present'][KEYS.index(key)]): raise ValueError('Wrong presence')\n            if state['present'] and not all(math.isfinite(v) for row in state['matrix_world'] for v in row): raise ValueError('Nonfinite transform')\n", "toy_car_collision.runtime_support": "\"\"\"Use the established project runtime and compatibility utilities.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport sys\nfrom pathlib import Path\nimport hashlib\n\nROOT=_PCVE_ROOT\nHERE = _PCVE_SCENE_ROOT\n\nfrom pcve_scene_runtime import python_for,render_prefix,append_render_options,parse_render_args,run_renderer\n\n\ndef implementation_hashes(directory):\n    files=list(Path(directory).glob('*.py'))\n    files += [ROOT/'clean_scripts'/n for n in ('pcve_scene_runtime.py','pcve_blender_compat.py','pcve_edit_dsl.py')]\n    files += [ROOT/'scripts/pcve_render_quality.py']\n    files += [ROOT/'assets/models'/n for n in ('futuristic_room.glb','hotwheels_technetium__www.vecarz.com.glb','cartoonish_toy_car.glb')]\n    files += list((ROOT/'assets'/'polyhaven'/'toy_car_collision').glob('*.jpg'))\n    return {str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in files if p.is_file()}\n", "toy_car_collision.scene_config": "\"\"\"SI units and independently editable toy-car initial conditions.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nfrom copy import deepcopy\nimport json\nimport math\n\nSCENE_NAME = 'toy_car_collision'\nBASELINE_PHYSICS = dict(driver_mass=.065, receiver_mass=.110, initial_velocity=.95,\n                        driver_friction=.12, receiver_friction=.14, receiver_speed_multiplier=1.,\n                        present=[1,1])\nPHYSICS_LIMITS = dict(driver_mass=(.01,3.), receiver_mass=(.01,3.),\n                      initial_velocity=(.01,4.), driver_friction=(.001,1.), receiver_friction=(.001,1.))\nTOTAL_FRAMES = 96\n\n\ndef defaults():\n    return dict(schema_version=1, scene=SCENE_NAME, seed=0, physics=deepcopy(BASELINE_PHYSICS),\n                render=dict(fps=24, duration_sec=4., slow_motion=1, resolution=[960,540], samples=48),\n                camera=dict(location=[-.25,-1.60,.70], target=[.60,0.,.04], lens_mm=23))\n\n\ndef merge(base, overrides):\n    result = deepcopy(base)\n    if not isinstance(overrides, dict): raise ValueError('Scenario overrides must be an object')\n    for key,value in overrides.items():\n        if key not in result: raise ValueError(f'Unknown scenario field: {key}')\n        result[key] = merge(result[key],value) if isinstance(value,dict) else deepcopy(value)\n    return result\n\n\ndef finite(value):\n    return isinstance(value,(int,float)) and not isinstance(value,bool) and math.isfinite(value)\n\n\ndef validate(s):\n    if set(s) - {'schema_version','scene','physics','render','camera','seed'}:\n        raise ValueError('Unknown scenario field')\n    if s['scene'] != SCENE_NAME or s['schema_version'] != 1: raise ValueError('Wrong scene/schema')\n    if set(s['physics']) != set(BASELINE_PHYSICS): raise ValueError('Unknown editable physics parameter')\n    if s['physics']['present'] not in ([1,1],[1,0]): raise ValueError('Only receiver deletion is supported')\n    for key,(low,high) in PHYSICS_LIMITS.items():\n        if not finite(s['physics'][key]) or not low <= s['physics'][key] <= high:\n            raise ValueError(f'{key} must be finite and within {low}..{high}')\n    if s['physics']['receiver_speed_multiplier'] != 1.:\n        raise ValueError('receiver_speed_multiplier is a mid-run knob; write it as '\n                         'SET car_b.speed ... AT FRAME n, not as a whole-clip override')\n    r=s['render']\n    if type(r['fps']) is not int or r['fps'] <= 0: raise ValueError('Invalid fps')\n    if type(r['slow_motion']) is not int or r['slow_motion'] not in (1,2,4,8) or 1440 % (r['fps']*r['slow_motion']):\n        raise ValueError('fps * slow_motion must divide the 1440 Hz simulation clock')\n    if not finite(r['duration_sec']) or not 0 < r['duration_sec'] <= 30 or round(r['fps']*r['slow_motion']*r['duration_sec']) < 2:\n        raise ValueError('Invalid duration')\n    if len(r['resolution']) != 2 or any(type(v) is not int or v <= 0 for v in r['resolution']): raise ValueError('Invalid resolution')\n    if type(r['samples']) is not int or r['samples'] < 1: raise ValueError('Invalid sample count')\n    if set(r) != {'fps','duration_sec','slow_motion','resolution','samples'}: raise ValueError('Unknown render field')\n    if set(s['camera']) != {'location','target','lens_mm'}: raise ValueError('Unknown camera field')\n    for key in ('location','target'):\n        if len(s['camera'][key]) != 3 or not all(finite(v) for v in s['camera'][key]): raise ValueError('Invalid camera vector')\n    if not finite(s['camera']['lens_mm']) or s['camera']['lens_mm'] <= 0: raise ValueError('Invalid lens')\n\n\ndef load_scenario(args):\n    s=merge(defaults(),json.loads(args.scenario_json.read_text(encoding='utf-8'))) if args.scenario_json else defaults()\n    if args.scenario_overrides_json: s=merge(s,json.loads(args.scenario_overrides_json.read_text(encoding='utf-8')))\n    for key in BASELINE_PHYSICS:\n        if getattr(args,key,None) is not None: s['physics'][key]=getattr(args,key)\n    for key in ('fps','duration_sec','slow_motion'):\n        if getattr(args,key,None) is not None: s['render'][key]=getattr(args,key)\n    validate(s)\n    return s\n\n\ndef add_scenario_arguments(parser):\n    from pathlib import Path\n    parser.add_argument('--scenario-json',type=Path)\n    parser.add_argument('--scenario-overrides-json',type=Path)\n    for key in PHYSICS_LIMITS: parser.add_argument('--'+key.replace('_','-'),type=float)\n    parser.add_argument('--fps',type=int)\n    parser.add_argument('--duration-sec',type=float)\n    parser.add_argument('--slow-motion',type=int,choices=(1,2,4,8))\n    return parser\n", "toy_car_collision.scene_environment": "\"\"\"Locally copied furnished room and independently tinted die-cast toy cars.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport math\nfrom pathlib import Path\nfrom .scene_geometry import DIMENSIONS\nMODELS=_PCVE_ROOT/'assets'/'models'\nAPPEARANCE_VERSION='desk-bed-clear-lane-two-distinct-toys-v2'\nROOM_ASSET='futuristic_room.glb'\nCAR_ASSET='hotwheels_technetium__www.vecarz.com.glb'\nRECEIVER_ASSET='cartoonish_toy_car.glb'\nCAR_ASSETS=(CAR_ASSET,RECEIVER_ASSET)\nROOM_ORIGIN=(-2.0,.82,.05)\nROOM_YAW=0.\n\ndef build_environment(bpy,scene):\n    from mathutils import Vector,Matrix\n    transform=Matrix.Rotation(ROOM_YAW,4,'Z')@Matrix.Translation(-Vector(ROOM_ORIGIN))\n    before=set(bpy.data.objects);bpy.ops.import_scene.gltf(filepath=str(MODELS/ROOM_ASSET))\n    bpy.context.view_layer.update()\n    for o in set(bpy.data.objects)-before:\n        o.animation_data_clear()\n        if o.type in ('LIGHT','CAMERA') or o.name.startswith(('Ammobox','Books.001_','Books.006_','ChineseSoldier','OfficeChair_')):\n            bpy.data.objects.remove(o,do_unlink=True);continue\n        if o.parent is None:o.matrix_world=transform@o.matrix_world\n    for m in bpy.data.materials:\n        if not m.use_nodes:continue\n        for n in m.node_tree.nodes:\n            if n.type=='BSDF_PRINCIPLED' and n.inputs.get('Emission Strength'):n.inputs['Emission Strength'].default_value=0\n    world=bpy.data.worlds.new('Soft apartment ambient');world.use_nodes=True;scene.world=world\n    world.node_tree.nodes['Background'].inputs['Color'].default_value=(.45,.55,.7,1)\n    world.node_tree.nodes['Background'].inputs['Strength'].default_value=.22\n    for name,loc,power,size,color in [('Broad window',(-.4,-.9,2.4),180,2.,(1.,.91,.78)),('Cool room bounce',(2.,1.,2.2),120,1.8,(.78,.86,1.))]:\n        bpy.ops.object.light_add(type='AREA',location=loc);o=bpy.context.object;o.name=name\n        o.data.energy=power;o.data.shape='DISK';o.data.size=size;o.data.color=color\n        o.rotation_euler=(Vector((.7,0,0))-o.location).to_track_quat('-Z','Y').to_euler()\n\ndef make_cars(bpy,present):\n    from .asset_import import import_car\n    objects={};wheels={}\n    for i,key in enumerate(('car_a','car_b')):\n        if not present[i]:continue\n        root,spin=import_car(MODELS/CAR_ASSETS[i],key,1,DIMENSIONS[i][0])\n        physics=bpy.data.objects.new(key+'_physics',None);bpy.context.collection.objects.link(physics)\n        root.parent=physics;root.rotation_mode='XYZ';root.rotation_euler=(0,0,math.pi/2)\n        for part in root.children_recursive:\n            if part.type!='MESH':continue\n            for slot in part.material_slots:\n                m=slot.material\n                if not m:continue\n                if i==1:\n                    if m.use_nodes:\n                        shader=m.node_tree.nodes.get('Principled BSDF')\n                        if shader and 'Material.002' in m.name:\n                            shader.inputs['Base Color'].default_value=(.025,.22,.31,1)\n                            shader.inputs['Roughness'].default_value=.3\n                            if shader.inputs.get('Coat Weight'):shader.inputs['Coat Weight'].default_value=.35\n                    continue\n                if 'Livery' not in m.name:continue\n                mat=m.copy();mat.name=key+'_paint';slot.material=mat\n                n=mat.node_tree.nodes;l=mat.node_tree.links;bs=n.get('Principled BSDF');base=bs.inputs['Base Color'];links=list(base.links)\n                if links:\n                    source=links[0].from_socket;l.remove(links[0]);mix=n.new('ShaderNodeMixRGB');mix.blend_type='MULTIPLY'\n                    mix.inputs[0].default_value=.78;mix.inputs[2].default_value=((.95,.15,.045,1) if i==0 else (.07,.36,.95,1))\n                    l.new(source,mix.inputs[1]);l.new(mix.outputs[0],base)\n                bs.inputs['Metallic'].default_value=.72;bs.inputs['Roughness'].default_value=.24\n                if bs.inputs.get('Coat Weight'):bs.inputs['Coat Weight'].default_value=.35\n        objects[key]=physics;wheels[key]=spin\n    return objects,wheels\n", "toy_car_collision.scene_geometry": "\"\"\"Metric dimensions, collision proxy and deterministic simulation clock.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nKEYS=('car_a','car_b')\n# Visual bounds at the chosen model scale: length, width, height in metres.\nDIMENSIONS=((.145,.145*189.85845947265625/363.76861572265625,.145*138.92532423161902/363.76861572265625),\n            (.180,.180*4.010020732879639/7.570144176483154,.180*3.5043145418167114/7.570144176483154))\nHALF_EXTENTS=tuple(tuple(v/2 for v in size) for size in DIMENSIONS)\nSTART_X=(-.42,0.)\nSIM_HZ=1440\nFLOOR_FRICTION=.5\n\ndef fixed_constants():\n    return dict(dimensions=DIMENSIONS,half_extents=HALF_EXTENTS,start_x=START_X,sim_hz=SIM_HZ,\n                floor_friction=FLOOR_FRICTION,gravity=9.81,pair_restitution=.32,\n                proxy='free 6-DOF rigid box; effective rolling drag at floor; visual wheels roll by travelled arc length')\n", "toy_car_collision": "\"\"\"Toy car to toy car momentum transfer in an imported furnished room.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n"}""")

_BUNDLE_SCENE_ALIAS = 'toy_car_collision'
_BUNDLE_ALIASES = ['asset_import', 'cache_contract', 'runtime_support', 'scene_config', 'scene_environment', 'scene_geometry', 'toy_car_collision', 'toy_car_collision.asset_import', 'toy_car_collision.cache_contract', 'toy_car_collision.runtime_support', 'toy_car_collision.scene_config', 'toy_car_collision.scene_environment', 'toy_car_collision.scene_geometry']

class _SceneBundleLoader(_bundle_abc.MetaPathFinder, _bundle_abc.Loader):
    def find_spec(self, fullname, path=None, target=None):
        if fullname not in _BUNDLE_SOURCES:
            return None
        package = (fullname == "scene_support" or fullname.count(".") == 1 and fullname.startswith("scene_support.") or fullname == _BUNDLE_SCENE_ALIAS)
        return _bundle_util.spec_from_loader(fullname, self, is_package=package)

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        name = module.__spec__.name
        package = module.__spec__.submodule_search_locations is not None
        if name == "scene_support":
            origin = _BUNDLE_SCENE / "scene_support" / "__init__.py"
        elif name == _BUNDLE_SCENE_ALIAS:
            origin = _BUNDLE_SCENE / "scene_support" / name / "__init__.py"
        elif name.startswith(_BUNDLE_SCENE_ALIAS + "."):
            origin = _BUNDLE_SCENE / "scene_support" / name.replace(".", "/")
            origin = origin.with_suffix(".py")
        elif name.startswith("scene_support."):
            tail = name.split(".", 1)[1]
            if package:
                origin = _BUNDLE_SCENE / "scene_support" / tail / "__init__.py"
            else:
                origin = _BUNDLE_SCENE / "scene_support" / tail.replace(".", "/")
                origin = origin.with_suffix(".py")
        else:
            origin = _BUNDLE_SCRIPTS / (name + ".py")
        module.__file__ = str(origin)
        module.__package__ = name if package else (_BUNDLE_SCENE_ALIAS if name.startswith(_BUNDLE_SCENE_ALIAS + ".") or name in ['asset_import', 'cache_contract', 'runtime_support', 'scene_config', 'scene_environment', 'scene_geometry'] else name.rpartition("." )[0])
        if package:
            module.__path__ = [str(_BUNDLE_SCENE)] if name == _BUNDLE_SCENE_ALIAS else []
        source = _BUNDLE_SOURCES[name]
        exec(compile(source, str(origin), "exec"), module.__dict__)

def install_scene_support():
    if not any(isinstance(item, _SceneBundleLoader) for item in _bundle_sys.meta_path):
        _bundle_sys.meta_path.insert(0, _SceneBundleLoader())

install_scene_support()



